WITH with_last AS (SELECT s.*, top1.event_type, top1.web_event_page FROM sessions s JOIN LATERAL (SELECT c.event_type, c.page AS web_event_page FROM web_events c WHERE c.session_id = s.id ORDER BY c.event_time DESC, c.id DESC LIMIT 1) top1 ON TRUE) SELECT id, customer_id, browser, country, event_type, web_event_page, CASE WHEN country RLIKE '^(TH|US)$' THEN 'EXTENDED' WHEN country RLIKE '^(SG|JP)$' THEN 'OTHER_ZONE' ELSE 'PRIORITY' END AS country_zone FROM with_last ORDER BY event_type DESC NULLS LAST;
